```go
func canMap(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	var fwd, back [256]byte
	for i := 0; i < len(a); i++ {
		x, y := a[i], b[i]
		if fwd[x] == 0 && back[y] == 0 {
			fwd[x], back[y] = y, x
			continue
		}
		if fwd[x] != y || back[y] != x {
			return false
		}
	}
	return true
}
```

